import{_ as t,o as i,c as a,a6 as s}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"Contribuer avec des changements ciblés","description":"","frontmatter":{"title":"Contribuer avec des changements ciblés","docId":"developer.contributing","translationKey":"developer.contributing","locale":"fr","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2e0522178ebee69ea5eb20fec3c0ec586f13950c51d658cb3a21843536b2f9f9","translationRevision":"d2a85dfdb0cb39bd82e5bdce7ba0bb2669a6943d130bb10c6ba95f2496786947","order":230},"headers":[],"relativePath":"fr/developer/contributing.md","filePath":"fr/developer/contributing.md","lastUpdated":1794611623000}'),n={name:"fr/developer/contributing.md"};function r(o,e,l,c,u,d){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="contributing-focused-changes" tabindex="-1">Contribuer avec des changements ciblés <a class="header-anchor" href="#contributing-focused-changes" aria-label="Permalink to &quot;Contribuer avec des changements ciblés {#contributing-focused-changes}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Préparer une modification qu’un autre contributeur peut examiner et vérifier. Lisez le <a href="https://github.com/nglmercer/TikTools-app/blob/remake/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a> du dépôt, les fichiers <code>AGENTS.md</code> applicables et la <a href="./setup.html">configuration</a> avant de modifier. Utilisez Bun 1.4.4, Rust 1.95 ou ultérieur si nécessaire, les fichiers de verrouillage du dépôt et une branche basée sur la cible prévue.</p><h2 id="define-and-implement-the-change" tabindex="-1">Définir et implémenter le changement <a class="header-anchor" href="#define-and-implement-the-change" aria-label="Permalink to &quot;Définir et implémenter le changement {#define-and-implement-the-change}&quot;">​</a></h2><ol><li>Examinez <code>git status</code> et préservez le travail des autres. Excluez du correctif les ressources générées, identifiants et bases locales.</li><li>Suivez le propriétaire actuel du code : cœur Rust pour les services, modules Control API pour les contrats, client typé pour la couverture SDK et <a href="./frontend.html">plan des couches de l’interface</a> pour la présentation.</li><li>Pour changer un contrat, mettez à jour sa définition canonique et régénérez ensemble les sorties dérivées. Ne maintenez pas manuellement un autre tableau complet de schémas RPC ou d’événements.</li><li>Gardez les implémentations propres aux plugins dans leurs paquets externes ; le code générique de l’hôte doit découvrir les manifestes plutôt qu’importer un plugin nommé.</li><li>Expliquez le déclencheur concret et le comportement résultant, y compris les parcours incomplets ou expérimentaux.</li></ol><h2 id="validate-proportionately" tabindex="-1">Valider de manière proportionnée <a class="header-anchor" href="#validate-proportionately" aria-label="Permalink to &quot;Valider de manière proportionnée {#validate-proportionately}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><p>Les changements d’implémentation native nécessitent aussi formatage, lint et tests Rust applicables ainsi que les contrôles CI requis. Une modification uniquement documentaire doit utiliser les vérifications documentaires et examiner ses commandes/liens sources plutôt que revendiquer une validation native à l’exécution. Le lanceur de tâches du projet définit les points d’entrée pris en charge ; utilisez le passage direct Cargo pour les options de cible natives spécifiques.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>La revue contient des modifications source ciblées, des preuves de validation utiles et des limites honnêtes. La politique du dépôt vise les pull requests vers <code>remake</code> ; les étiquettes de version sont contrôlées par les mainteneurs. Les instructions de contribution sont disponibles, mais la protection des branches et la configuration des contrôles distants relèvent des administrateurs, pas de garanties fournies par une page Markdown.</p><h2 id="recover" tabindex="-1">Récupérer <a class="header-anchor" href="#recover" aria-label="Permalink to &quot;Récupérer {#recover}&quot;">​</a></h2><p>Si la validation échoue à cause d’une dépendance ou bibliothèque de plateforme manquante, signalez et réparez cet environnement plutôt que d’affaiblir une vérification. Si les fichiers générés divergent, régénérez-les depuis leur source et examinez les différences. Ne publiez jamais cookies de session, clés, identifiants ou captures d’événements non expurgées. Si la source et une ancienne conception divergent, décrivez l’écart et utilisez l’implémentation actuelle pour les conseils publics. N’écrasez pas les fichiers en attente d’un autre propriétaire pour donner une apparence cohérente à un vaste nettoyage.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>Les sceaux sont distincts : <code>sourceRevision</code> hache le corps anglais actuel, <code>translationRevision</code> le corps localisé de cet article (sans frontmatter ni espaces extérieurs). Après revue source/traductions, lancez <code>bun docs/scripts/record-review.ts developer/example.md</code>. Toute édition ultérieure invalide le sceau correspondant. Cela détecte la dérive, pas l’identité humaine ni l’équivalence sémantique : comparez commandes, IDs RPC/environnement, clés payload, limites, activation/récupération et négations. Traduisez toute la prose en gardant les instructions techniques.</p><p>Pour une migration divisée, notez chaque sujet/titre original et sa destination concrète dans la carte, avec fragment pour une section. Le checker valide fichiers/fragments et octets historiques ; la revue éditoriale établit encore la couverture thématique. Ne modifiez pas originaux/provenance historiques pour faire réussir un contrôle.</p>`,15)])])}const m=t(n,[["render",r]]);export{h as __pageData,m as default};
